#!/usr/bin/env bash
# Fully generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
#
# Self-test for tests/check_pr_queue.sh. A stub `gh` answers `pr list` and
# `pr view` from files, so the row shape, the single `UNKNOWN` re-read, and the
# two unfinished-snapshot FAILs are pinned offline. The stub dispatches on the
# `list`/`view` verb and answers `view` per PR number, which is what makes the
# re-read case distinguishable from a first-pass value.
#
# Exit codes: 0 all cases pass, 1 a case mismatched, 2 setup failed.
set -u

. "${BASH_SOURCE[0]%/*}/gate_lib.sh"

gate_top
GATE="$ROOT/tests/check_pr_queue.sh"
[ -f "$GATE" ] || { echo "self-test: gate not found at $GATE" >&2; exit 2; }

gate_sandbox pime-pr-queue-selftest || { echo "self-test: no sandbox" >&2; exit 2; }
SANDBOX=$tmp

cat >"$SANDBOX/gh" <<'STUB'
#!/usr/bin/env bash
verb=${2:-}
# `gh pr list|view` puts the verb in $2; `gh api <path>` puts the path there.
[ "${1:-}" = api ] && verb=api
case "$verb" in
    list) [ -f "${STUB_LIST:-}" ] && cat "$STUB_LIST"; exit 0 ;;
    view)
        num=${3:-}
        [ -f "${STUB_VIEW:-}" ] || exit 0
        awk -v n="$num" '$1 == n { print $2; found = 1; exit } END { if (!found) print "UNKNOWN" }' \
            "$STUB_VIEW"
        exit 0 ;;
    api)
        path=${2:-}
        case "$path" in
            *pulls\?*) [ -f "${STUB_API_PULLS:-}" ] && cat "$STUB_API_PULLS" ;;
            *pulls/*)
                num=${path##*pulls/}; num=${num%%[!0-9]*}
                if [ -f "${STUB_API_VIEW:-}" ]; then
                    awk -v n="$num" '$1 == n { print $2; found = 1; exit } END { if (!found) print "UNKNOWN" }' \
                        "$STUB_API_VIEW"
                else
                    [ -f "${STUB_API_PULLS:-}" ] || exit 0
                    awk -F'|' -v n="$num" '$1 == n { print $3; exit }' "$STUB_API_PULLS"
                fi ;;
            *check-runs*)
                rest=${path#*commits/}; sha=${rest%%/*}
                [ -f "${STUB_API_CHECKS:-}" ] || exit 0
                awk -F'|' -v s="$sha" '$1 == s { print $2; exit }' "$STUB_API_CHECKS" ;;
        esac
        exit 0 ;;
esac
exit 0
STUB
# `cat >` leaves the stub 644, and a non-executable file is invisible to
# `command -v`: the gate then falls back to whatever `gh` the box has, and a
# runner without a token answers empty, which reads as a 125 for every case.
chmod 755 "$SANDBOX/gh"

failures=0
check() { # name want got
    if [ "$2" = "$3" ]; then
        printf 'ok    %s (rc %s)\n' "$1" "$3"
    else
        printf 'FAIL  %s: want rc %s, got rc %s\n' "$1" "$2" "$3"
        failures=$((failures + 1))
    fi
}

run_gate() {
    ( cd "$ROOT" && PATH="$SANDBOX:$PATH" GH_BIN="$SANDBOX/gh" STUB_LIST="$SANDBOX/list" \
        STUB_VIEW="$SANDBOX/view" STUB_API_PULLS="$SANDBOX/api_pulls" \
        STUB_API_CHECKS="$SANDBOX/api_checks" STUB_API_VIEW="$SANDBOX/api_view" \
        bash "$GATE" EasyIME/PIME ) >/dev/null 2>&1
    printf '%s' "$?"
}

# 1. A complete snapshot: two PRs, one with no check reported yet.
printf '1029|2cfae129abcd|MERGEABLE|SUCCESS,SUCCESS\n881|948f8db0ffff|MERGEABLE|\n' \
    >"$SANDBOX/list"
: >"$SANDBOX/view"
check "complete snapshot" 0 "$(run_gate)"

# 2. A row whose head SHA is missing: the truncated-field class of miss.
printf '1029||MERGEABLE|SUCCESS\n' >"$SANDBOX/list"
check "row without a head SHA" 1 "$(run_gate)"

# 3. A first-pass UNKNOWN the single re-read settles.
printf '898|d950d61b|UNKNOWN|FAILURE,FAILURE\n' >"$SANDBOX/list"
printf '898 CONFLICTING\n' >"$SANDBOX/view"
check "UNKNOWN settled by the re-read" 0 "$(run_gate)"

# 4. An UNKNOWN that survives the re-read: an unsettled disposition.
printf '898 UNKNOWN\n' >"$SANDBOX/view"
check "UNKNOWN after the re-read" 1 "$(run_gate)"

# 5. Two open PRs on one head: the shared-head shape that cost #1014 its
#    `ready to merge` state (one force-push moves both evidence trails).
printf '1013|abcdef12|MERGEABLE|SUCCESS\n1014|abcdef12|MERGEABLE|SUCCESS\n' \
    >"$SANDBOX/list"
check "two PRs sharing one head" 1 "$(run_gate)"

# 6. A row whose head is not the tip of its own local branch, then a row that
#    matches it: the posted CI evidence belongs to the head, so a tip that has
#    moved on is a stale trail rather than a green light.
tip=$( cd "$ROOT" && git rev-parse local/stroke-parked 2>/dev/null )
if [ -n "$tip" ]; then
    printf '77|0000000000000000000000000000000000000000|MERGEABLE||local/stroke-parked\n' \
        >"$SANDBOX/list"
    check "row head behind the branch tip" 1 "$(run_gate)"
    printf '77|%s|MERGEABLE||local/stroke-parked\n' "$tip" >"$SANDBOX/list"
    check "row head at the branch tip" 0 "$(run_gate)"
else
    echo "skip    head-vs-tip cases (no local/stroke-parked in this checkout)"
fi

# 7. No `gh` on this box: not applicable.
( cd "$ROOT" && GH_BIN=pime-no-such-gh bash "$GATE" EasyIME/PIME ) >/dev/null 2>&1
check "no gh on PATH" 125 "$?"

# 8. The repo answers nothing at all: not applicable, not red.
: >"$SANDBOX/list"
check "empty queue" 125 "$(run_gate)"

# 9. The REST fallback a tokenless box lands on: `pr list` answers nothing, so
#    the rows come from `api repos/<nwo>/pulls` plus one `check-runs` read per
#    head. A null `mergeable` is the same unsettled state the enum's UNKNOWN is.
: >"$SANDBOX/list"
printf '1029|2cfae129abcd|MERGEABLE|nometa-rest-9\n881|948f8db0ffff|true|\n' \
    >"$SANDBOX/api_pulls"
printf '2cfae129abcd|SUCCESS,SUCCESS\n948f8db0ffff|\n' >"$SANDBOX/api_checks"
check "REST rows assembled from the pulls and check-runs endpoints" 0 "$(run_gate)"

# 10. A null `mergeable` the per-PR REST read settles: the same single re-read
#     the GraphQL shape gets, so a tokenless snapshot is not a weaker one.
printf '1029|2cfae129abcd|UNKNOWN|nometa-rest-9\n' >"$SANDBOX/api_pulls"
printf '1029 MERGEABLE\n' >"$SANDBOX/api_view"
check "REST null settled by the per-PR read" 0 "$(run_gate)"

# 11. A null that survives the per-PR read is still no disposition.
printf '1029 UNKNOWN\n' >"$SANDBOX/api_view"
check "REST null after the re-read" 1 "$(run_gate)"

# 12. The exhausted REST window a tokenless box hits: the limit body is not a
#     row, and a snapshot that cannot be taken is 125 rather than a red.
printf '{"message":"API rate limit exceeded for 10.0.0.1.","documentation_url":"https://docs.github.com/rest/overview/resources-in-the-rest-api#rate-limiting"}' \
    >"$SANDBOX/api_pulls"
check "REST limit body reads as not applicable" 125 "$(run_gate)"

# 13. The limit body landing in one row's field rather than the whole listing:
#     the array came through, the per-item `mergeable` did not.
printf '1029|2cfae129abcd|{"message":"API rate limit exceeded for 10.0.0.1.","documentation_url":"https://docs.github.com/rest/overview/resources-in-the-rest-api#rate-limiting"}\n' \
    >"$SANDBOX/api_pulls"
check "limit body in one row field reads as not applicable" 125 "$(run_gate)"

if [ "$failures" -ne 0 ]; then
    printf 'Self-test failed (%d case(s))\n' "$failures" >&2
    exit 1
fi
echo "Self-test passed"
